1	// Command govflow is the DAO 治理提案与执行平台 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"errors"
7		"flag"
8		"fmt"
9		"io"
10		"os"
11		"strings"
12	
13		"github.com/gzhysuiioo/govflow-proposals/govflow"
14		"github.com/gzhysuiioo/govflow-proposals/govflow/batchreg"
15	)
16	
17	const batchRegisterUsage = `usage: govflow batch-register --registry FILE --batch ID --product ID --quantity N --unit UNIT
18	run 'govflow help' for the full description and the registry file format.
19	`
20	
21	const batchImportUsage = `usage: govflow batch-import --registry FILE --input FILE
22	run 'govflow help' for the full description and the registry file format.
23	`
24	
25	func main() {
26		if err := run(os.Args[1:]); err != nil {
27			fmt.Fprintln(os.Stderr, "govflow:", err)
28			var ue *usageError
29			if errors.As(err, &ue) {
30				fmt.Fprint(os.Stderr, ue.usage)
31			}
32			os.Exit(1)
33		}
34	}
35	
36	type usageError struct {
37		msg   string
38		usage string
39	}
40	
41	func (e *usageError) Error() string { return e.msg }
42	
43	func run(args []string) error {
44		command := "demo"
45		if len(args) > 0 {
46			command = args[0]
47		}
48		switch command {
49		case "demo":
50			runDemo()
51			return nil
52		case "version":
53			fmt.Println("govflow 0.1.0")
54			return nil
55		case "help", "-h", "--help":
56			fmt.Print(rootUsage())
57			return nil
58		case "batch-register":
59			return runBatchRegister(args[1:], os.Stdout)
60		case "batch-import":
61			return runBatchImport(args[1:], os.Stdout)
62		default:
63			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
64			fmt.Fprint(os.Stderr, rootUsage())
65			os.Exit(2)
66			return nil
67		}
68	}
69	
70	func rootUsage() string {
71		return `govflow - DAO 治理提案与执行平台 / supply-chain batch registry
72	
73	usage:
74	  govflow                                  run the built-in demo (default)
75	  govflow demo                             run the built-in demo
76	  govflow version                          print the version
77	  govflow help                             show this help
78	  govflow batch-register --registry FILE \
79	      --batch ID --product ID --quantity N --unit UNIT
80	                                           register one supply-chain batch in
81	                                           the registry FILE (see below)
82	  govflow batch-import --registry FILE --input FILE
83	                                           register every batch listed in the
84	                                           JSON manifest FILE into the registry
85	                                           FILE, all records or none
86	
87	batch-register flags:
88	  --registry FILE   registry file to read and write (required)
89	  --batch ID        batch number; unique within one registry file (required)
90	  --product ID      product number the batch belongs to (required)
91	  --quantity N      positive decimal integer, digits 0-9 only, leading
92	                    zeros allowed, max 9223372036854775807 (required)
93	  --unit UNIT       measurement unit, e.g. kg or box (required)
94	
95	batch-import flags:
96	  --registry FILE   registry file to read and write (required)
97	  --input FILE      read-only JSON manifest (required); a non-empty array of
98	                    objects carrying exactly batch, product, quantity and
99	                    unit. Text fields must be non-blank after trimming, and
100	                    quantity must be a JSON integer from 1 to
101	                    9223372036854775807 (no strings, fractions or exponents)
102	
103	The whole manifest is rejected unless every record can be registered or
104	confirmed as a duplicate: a batch id already stored or seen earlier in the
105	manifest must match product, quantity and unit exactly, or none of the new
106	batches are saved and the error names the 1-based record position, the batch
107	id and the mismatching field(s). On success stdout contains one JSON object
108	whose results array keeps manifest order, each entry carrying the normalized
109	four fields plus status "created" or "duplicate"; new batches are appended
110	in first-occurrence order and an all-duplicate manifest leaves the registry
111	file byte-for-byte untouched.
112	
113	Batch, product and unit values have leading and trailing whitespace removed
114	and must be non-empty afterwards; interior characters and casing are kept
115	("B1" and "b1" are different batches). One invocation registers one batch.
116	
117	Batch, product and unit must be valid UTF-8 text in every source: command
118	line flags, import manifest records and stored registry records. A value
119	containing malformed UTF-8 bytes (or a JSON string holding a lone surrogate
120	escape such as "\ud800") is rejected and never replaced with the U+FFFD
121	replacement character, so distinct inputs cannot collapse onto one batch
122	id; the error names the parameter, or the manifest/registry file with the
123	1-based record position and field (plus the batch id only when it is itself
124	valid and unambiguous). The same rule applies to field NAMES in the JSON
125	files: a name with malformed bytes or a lone surrogate escape rejects the
126	whole operation with an invalid-field-name error naming the file (plus the
127	1-based record position, and the batch id when unambiguous, for record
128	level problems) — it is never reported as an unknown field under the
129	substituted text. A genuinely entered U+FFFD character is ordinary
130	text, non-ASCII ids (Chinese text, emoji, ...) are welcome, and a JSON
131	escape means the same text as the character written directly.
132	
133	On success stdout contains a single JSON object, e.g.
134	  {"batch":"B-001","product":"P-7","quantity":120,"unit":"kg","status":"created"}
135	status is "created" for a new record and "duplicate" when the same batch was
136	already registered with the identical product, quantity and unit; a duplicate
137	does not rewrite the file and is safe to retry. Registering an existing batch
138	with any different field is rejected; the error names the batch and the
139	mismatching field(s) and no record is changed.
140	
141	registry file format (UTF-8 JSON, human-inspectable):
142	  {
143	    "version": 1,
144	    "batches": [
145	      {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
146	    ]
147	  }
148	A missing file is created on first registration, and a registry whose parent
149	directory does not yet exist is created together with that directory, as long
150	as the path never climbs back out of a directory it just descended into. A
151	path that first passes through a directory that does not exist and then steps
152	back with ".." — store/missing/../batches.json while store/missing is absent —
153	names no file the way the filesystem resolves names and is rejected outright:
154	the missing directory is not created to make the path valid, the name left
155	after dropping the missing segment is not written (an existing registry there
156	is never overwritten), and no temporary file remains. A ".." that follows a
157	directory which really exists keeps working by the real directory relations.
158	The registry path may be a
159	symbolic link to an existing registry file: new batches are saved into the
160	linked file (a relative link target is resolved against the link's own
161	directory), the link itself is left untouched and the target keeps its
162	permissions. A symbolic link may also sit on a DIRECTORY component of the
163	path, together with "..": reads and saves resolve the path the way the
164	filesystem does, so with work/alias -> store/child the path
165	work/alias/../batches.json names store/batches.json, and a new batch is
166	appended to that real file rather than to a same-named file in the link's
167	parent directory. The temporary file is prepared in the real file's own
168	directory, so a read-only work directory (read and enter, but not create)
169	does not block the save and nothing is created under work; only an
170	unwritable real target directory rejects it. A link whose target does not
171	exist, or a loop of links, is rejected — the target is never created and
172	the link is never replaced. An
173	existing file that is empty, cannot be read in this format, or contains
174	several records with the same batch number is rejected outright and never
175	overwritten. "This format"
176	is strict: the root object must carry exactly version (the integer 1) and
177	batches (an array, empty allowed), each record exactly the four lowercase
178	fields batch, product, quantity and unit; missing, null, mistyped, unknown
179	or case-variant fields (Version, Batch, ...) are rejected, and so is any
180	field appearing twice in one object — even with identical values, even when
181	one spelling hides behind a JSON escape. The error names the file, the
182	field and the reason, plus the 1-based record position (and the batch id
183	when it is unambiguous) for record-level problems. Failures print
184	the reason to stderr and exit non-zero without touching the registry.
185	`
186	}
187	
188	func runBatchRegister(args []string, stdout io.Writer) error {
189		fs := flag.NewFlagSet("batch-register", flag.ContinueOnError)
190		fs.SetOutput(io.Discard)
191		registryPath := fs.String("registry", "", "registry `file` to read and write")
192		batchRaw := fs.String("batch", "", "batch number (unique within the registry)")
193		productRaw := fs.String("product", "", "product number")
194		quantityRaw := fs.String("quantity", "", "positive decimal integer quantity")
195		unitRaw := fs.String("unit", "", "measurement unit")
196		if err := fs.Parse(args); err != nil {
197			if errors.Is(err, flag.ErrHelp) {
198				fmt.Fprint(stdout, rootUsage())
199				return nil
200			}
201			return &usageError{msg: "batch-register: " + err.Error(), usage: batchRegisterUsage}
202		}
203		if fs.NArg() != 0 {
204			return &usageError{
205				msg:   fmt.Sprintf("batch-register: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
206				usage: batchRegisterUsage,
207			}
208		}
209	
210		// Missing or malformed input must never create or modify the registry
211		// file, so required flags are checked before reading or writing anything.
212		required := []struct {
213			name  string
214			value string
215		}{
216			{"--registry", *registryPath},
217			{"--batch", *batchRaw},
218			{"--product", *productRaw},
219			{"--quantity", *quantityRaw},
220			{"--unit", *unitRaw},
221		}
222		var missing []string
223		for _, f := range required {
224			if f.value == "" {
225				missing = append(missing, f.name)
226			}
227		}
228		if len(missing) > 0 {
229			return &usageError{
230				msg:   "batch-register: missing required flag(s): " + strings.Join(missing, ", "),
231				usage: batchRegisterUsage,
232			}
233		}
234	
235		batch, err := batchreg.NormalizeField(*batchRaw)
236		if err != nil {
237			return &usageError{msg: "batch-register: invalid --batch: " + err.Error(), usage: batchRegisterUsage}
238		}
239		product, err := batchreg.NormalizeField(*productRaw)
240		if err != nil {
241			return &usageError{msg: "batch-register: invalid --product: " + err.Error(), usage: batchRegisterUsage}
242		}
243		unit, err := batchreg.NormalizeField(*unitRaw)
244		if err != nil {
245			return &usageError{msg: "batch-register: invalid --unit: " + err.Error(), usage: batchRegisterUsage}
246		}
247		quantity, err := batchreg.ParseQuantity(*quantityRaw)
248		if err != nil {
249			return &usageError{msg: "batch-register: invalid --quantity: " + err.Error(), usage: batchRegisterUsage}
250		}
251	
252		reg, existed, err := batchreg.Load(*registryPath)
253		if err != nil {
254			return err
255		}
256		outcome, err := batchreg.Register(reg, batchreg.Input{
257			Batch: batch, Product: product, Quantity: quantity, Unit: unit,
258		})
259		if err != nil {
260			return err
261		}
262		if outcome.Created {
263			if err := batchreg.Save(*registryPath, reg); err != nil {
264				if !existed {
265					// Nothing was registered before; drop any partial new file.
266					removePartialNewRegistry(*registryPath)
267				}
268				return err
269			}
270		}
271	
272		status := "duplicate"
273		if outcome.Created {
274			status = "created"
275		}
276		result := struct {
277			Batch    string `json:"batch"`
278			Product  string `json:"product"`
279			Quantity int64  `json:"quantity"`
280			Unit     string `json:"unit"`
281			Status   string `json:"status"`
282		}{
283			Batch:    outcome.Batch.Batch,
284			Product:  outcome.Batch.Product,
285			Quantity: outcome.Batch.Quantity,
286			Unit:     outcome.Batch.Unit,
287			Status:   status,
288		}
289		payload, err := json.Marshal(result)
290		if err != nil {
291			return err
292		}
293		_, err = fmt.Fprintln(stdout, string(payload))
294		return err
295	}
296	
297	func runBatchImport(args []string, stdout io.Writer) error {
298		fs := flag.NewFlagSet("batch-import", flag.ContinueOnError)
299		fs.SetOutput(io.Discard)
300		registryPath := fs.String("registry", "", "registry `file` to read and write")
301		inputPath := fs.String("input", "", "read-only JSON manifest `file` to import")
302		if err := fs.Parse(args); err != nil {
303			if errors.Is(err, flag.ErrHelp) {
304				fmt.Fprint(stdout, rootUsage())
305				return nil
306			}
307			return &usageError{msg: "batch-import: " + err.Error(), usage: batchImportUsage}
308		}
309		if fs.NArg() != 0 {
310			return &usageError{
311				msg:   fmt.Sprintf("batch-import: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
312				usage: batchImportUsage,
313			}
314		}
315		if *registryPath == "" || *inputPath == "" {
316			var missing []string
317			if *registryPath == "" {
318				missing = append(missing, "--registry")
319			}
320			if *inputPath == "" {
321				missing = append(missing, "--input")
322			}
323			return &usageError{
324				msg:   "batch-import: missing required flag(s): " + strings.Join(missing, ", "),
325				usage: batchImportUsage,
326			}
327		}
328	
329		// The manifest is read-only and is parsed (and fully validated) before
330		// the registry is loaded or written, so bad input cannot touch it.
331		data, err := os.ReadFile(*inputPath)
332		if err != nil {
333			return fmt.Errorf("batch-import: cannot read input file %q: %w", *inputPath, err)
334		}
335		inputs, err := batchreg.ParseManifest(data)
336		if err != nil {
337			return fmt.Errorf("batch-import: invalid input file %q: %w", *inputPath, err)
338		}
339	
340		reg, existed, err := batchreg.Load(*registryPath)
341		if err != nil {
342			return fmt.Errorf("batch-import: %w", err)
343		}
344		outcomes, err := batchreg.Import(reg, inputs)
345		if err != nil {
346			return fmt.Errorf("batch-import: %w", err)
347		}
348	
349		type importResultJSON struct {
350			Batch    string `json:"batch"`
351			Product  string `json:"product"`
352			Quantity int64  `json:"quantity"`
353			Unit     string `json:"unit"`
354			Status   string `json:"status"`
355		}
356		results := make([]importResultJSON, len(outcomes))
357		anyCreated := false
358		for i, o := range outcomes {
359			status := "duplicate"
360			if o.Created {
361				status = "created"
362				anyCreated = true
363			}
364			results[i] = importResultJSON{
365				Batch:    o.Batch.Batch,
366				Product:  o.Batch.Product,
367				Quantity: o.Batch.Quantity,
368				Unit:     o.Batch.Unit,
369				Status:   status,
370			}
371		}
372	
373		// An all-duplicate manifest must leave bytes and mtime untouched, so the
374		// registry is written only when at least one record was newly created.
375		if anyCreated {
376			if err := batchreg.Save(*registryPath, reg); err != nil {
377				if !existed {
378					// The registry never existed before this import; drop any
379					// partial new file so a failed save leaves nothing behind.
380					removePartialNewRegistry(*registryPath)
381				}
382				return fmt.Errorf("batch-import: %w", err)
383			}
384		}
385	
386		payload, err := json.Marshal(struct {
387			Results []importResultJSON `json:"results"`
388		}{Results: results})
389		if err != nil {
390			return fmt.Errorf("batch-import: %w", err)
391		}
392		_, err = fmt.Fprintln(stdout, string(payload))
393		if err != nil {
394			return fmt.Errorf("batch-import: %w", err)
395		}
396		return nil
397	}
398	
399	// removePartialNewRegistry drops a partially written new registry file after
400	// a failed first save. A symbolic link is never removed: the link is the
401	// user's pointer to the real registry file, not a partial creation of this
402	// run.
403	func removePartialNewRegistry(path string) {
404		info, err := os.Lstat(path)
405		if err != nil || info.Mode()&os.ModeSymlink != 0 {
406			return
407		}
408		os.Remove(path)
409	}
410	
411	func runDemo() {
412		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
413			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
414		if err := govflow.Vote(&proposal, 700, true); err != nil {
415			fmt.Println("vote refused:", err)
416		}
417		if err := govflow.Vote(&proposal, 200, false); err != nil {
418			fmt.Println("vote refused:", err)
419		}
420		next := govflow.Tally(&proposal)
421		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
422		proposal.State = next
423		proposal.TimelockEnd = 400
424		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
425	}
426

