631	// duplicateField returns the first field name appearing more than once.
632	func duplicateField(fields []objectField) (string, bool) {
633		seen := make(map[string]struct{}, len(fields))
634		for _, f := range fields {
635			if _, dup := seen[f.key]; dup {
636				return f.key, true
637			}
638			seen[f.key] = struct{}{}
639		}
640		return "", false
641	}
642	
643	// findField returns the raw value of the first member named name.
644	func findField(fields []objectField, name string) (json.RawMessage, bool) {
645		for _, f := range fields {
646			if f.key == name {
647				return f.value, true
648			}
649		}
650		return nil, false
651	}
652	
653	// countField counts the members named name.
654	func countField(fields []objectField, name string) int {
655		n := 0
656		for _, f := range fields {
657			if f.key == name {
658				n++
659			}
660		}
661		return n
662	}
