883	// ImportResult is one entry of an Import outcome: the normalized record in
884	// manifest order plus whether it was newly created or already present.
885	type ImportResult struct {
886		Batch   Batch
887		Created bool
888	}
889	
890	// validateManifestInput applies the same effective-value rules to one
891	// directly submitted record that Register enforces for single entries and
892	// parseManifestRecord enforces for file records: the three text fields must
893	// be valid UTF-8 and must not be empty strings, and quantity must lie in
894	// 1..MaxQuantity. Text is checked verbatim — direct submissions get no
895	// whitespace trimming or case folding (the command-line entry normalizes
896	// before constructing the Input), so whitespace-only text is accepted as
897	// ordinary non-empty text. pos is the record's 1-based position in this
898	// submission. The returned *ManifestRecordError names the offending field
899	// in its reason and cites the batch id only when that id is itself
900	// non-empty, valid UTF-8 text; it is never invented or substituted when the
901	// batch field is empty or malformed.
902	func validateManifestInput(in Input, pos int) error {
903		// batchID is "" whenever the batch field itself is empty or malformed, so
904		// it is safe to attach it to whichever error follows.
905		batchID := safeBatchIDForError(in.Batch)
906		// Import reports an encoding problem anywhere in the three text fields
907		// before any empty-text problem; quantity problems come after both.
908		issues := inspectRecordText(in.Batch, in.Product, in.Unit)
909		if issue, bad := firstTextIssue(issues, textEncoding); bad {
910			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: (&EncodingError{Field: issue.field}).Error()}
911		}
912		if issue, bad := firstTextIssue(issues, textEmpty); bad {
913			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: fmt.Sprintf("field %q must not be empty", issue.field)}
914		}
915		switch classifyDecodedQuantity(in.Quantity) {
916		case decodedQtyNotPositive:
917			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: `field "quantity" must be greater than zero`}
918		case decodedQtyAboveMax:
919			return &ManifestRecordError{Position: pos, Batch: batchID,
920				Reason: fmt.Sprintf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)}
921		}
922		return nil
923	}
924	
925	// Import validates every record of inputs before appending anything: the
926	// whole manifest fails if any record carries invalid UTF-8, an empty text
927	// field or a quantity outside 1..MaxQuantity — whether its batch id is new,
928	// already stored or seen earlier in this submission — or if any record
929	// conflicts with a stored record or with an earlier manifest record, and reg
930	// is left untouched on error. A reg that already holds two records under one
931	// batch id (only possible when it was assembled directly, since Load refuses
932	// such files) likewise fails the whole submission with a *DuplicateIDError
933	// naming the id and the two 1-based stored positions — checked after the
934	// version and record validations above, before any create, duplicate
935	// confirmation or conflict, and leaving reg exactly as handed in. Directly
936	// submitted text is kept verbatim. New
937	// batch ids are appended in first-occurrence order; an id already stored or
938	// introduced earlier in the same manifest is confirmed as a duplicate only
939	// when product, quantity and unit all match. Results come back in manifest
940	// order; Created is false for duplicates.
941	func Import(reg *Registry, inputs []Input) (results []ImportResult, err error) {
942		if reg.Version != FormatVersion {
943			return nil, fmt.Errorf("unsupported registry version %d", reg.Version)
944		}
945		if len(inputs) == 0 {
946			return nil, errors.New("manifest must contain at least one record")
947		}
948		// Reject malformed text and non-effective values before touching
949		// anything; this covers records handed in directly by Go callers the
950		// same way ParseManifest covers file records, so a blank text field or a
951		// non-positive quantity can never reach the new/duplicate/conflict logic
952		// below and end up in a file the reader would refuse. Text is checked
953		// verbatim: direct submissions get no trimming or case folding (only the
954		// command-line entry normalizes, before building the Input).
955		for i, in := range inputs {
956			if err := validateManifestInput(in, i+1); err != nil {
957				return nil, err
958			}
959		}
960	
961		// A registry that already holds two records under one id — possible only
962		// when the caller assembled it directly, since Load refuses such files —
963		// rejects the whole submission before any create, duplicate confirmation
964		// or conflict is weighed: the existing records are ambiguous and Import
965		// must neither pick one of them as the id's record nor repair the
966		// registry on its own.
967		if dup := storedDuplicateID(reg); dup != nil {
968			return nil, dup
969		}
970	
971		// Work on a copy: a rejected manifest must never partially land in reg.
972		working := append([]Batch(nil), reg.Batches...)
973		indexByID := make(map[string]int, len(working))
974		for i, b := range working {
975			indexByID[b.Batch] = i
976		}
977		firstPos := make(map[string]int, len(inputs)) // manifest 1-based position of a newly introduced id
978	
979		out := make([]ImportResult, len(inputs))
980		for i, in := range inputs {
981			pos := i + 1
982			if idx, known := indexByID[in.Batch]; known {
983				existing := working[idx]
984				diffs := diffFields(existing, in)
985				if len(diffs) > 0 {
986					if prev, inManifest := firstPos[in.Batch]; inManifest {
987						return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "manifest", PrevPos: prev}
988					}
989					return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "registry"}
990				}
991				out[i] = ImportResult{Batch: existing, Created: false}
992				continue
993			}
994			b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
995			working = append(working, b)
996			indexByID[in.Batch] = len(working) - 1
997			firstPos[in.Batch] = pos
998			out[i] = ImportResult{Batch: b, Created: true}
999		}
1000	
1001		reg.Batches = working
1002		return out, nil
1003	}
1004	
1005	// diffFields lists the members of product, quantity and unit in which in
1006	// differs from existing, in that fixed order.
1007	func diffFields(existing Batch, in Input) []string {
1008		var diffs []string
1009		if existing.Product != in.Product {
1010			diffs = append(diffs, "product")
1011		}
1012		if existing.Quantity != in.Quantity {
1013			diffs = append(diffs, "quantity")
1014		}
1015		if existing.Unit != in.Unit {
1016			diffs = append(diffs, "unit")
1017		}
1018		return diffs
1019	}
