1068	// validateForSave checks every record of reg against the rules Load enforces,
1069	// so a hand-assembled registry cannot be persisted in a shape the reader
1070	// would refuse. Records are checked in order and the first violation is
1071	// reported as a *FormatError naming the 1-based record position, the field
1072	// and the reason; the batch id is attached only when it is itself non-empty,
1073	// valid UTF-8 text — never a U+FFFD substitution for a malformed id. A batch
1074	// id seen twice is reported as a *DuplicateIDError carrying both 1-based
1075	// positions, even when the two records are identical: Save persists records,
1076	// it never confirms duplicates or merges them. Text is checked verbatim —
1077	// no trimming, no case folding — and reg is never modified.
1078	func validateForSave(reg *Registry) error {
1079		seen := make(map[string]int, len(reg.Batches))
1080		for i, b := range reg.Batches {
1081			pos := i + 1
1082			batchID := safeBatchIDForError(b.Batch)
1083			// Save reports the first problem in batch, product, unit field
1084			// order, with a field's encoding problem ahead of its empty-string
1085			// problem — exactly the order inspectRecordText lists issues in.
1086			if issues := inspectRecordText(b.Batch, b.Product, b.Unit); len(issues) > 0 {
1087				issue := issues[0]
1088				if issue.kind == textEncoding {
1089					return &FormatError{Position: pos, Batch: batchID, Field: issue.field,
1090						Reason: "must be valid UTF-8 text: malformed bytes are rejected instead of being replaced with U+FFFD"}
1091				}
1092				return &FormatError{Position: pos, Batch: batchID, Field: issue.field, Reason: "must not be empty"}
1093			}
1094			if !quantityInRange(b.Quantity) {
1095				return &FormatError{Position: pos, Batch: batchID, Field: "quantity",
1096					Reason: fmt.Sprintf("must be between 1 and %d", MaxQuantity)}
1097			}
1098			if first, dup := seen[b.Batch]; dup {
1099				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
1100			}
1101			seen[b.Batch] = pos
1102		}
1103		return nil
1104	}
