1106	// WriteTempContent and RenameTempFile are the two failure-prone steps of the
1107	// atomic save — writing the new content into the temporary file, and replacing
1108	// the target with it — kept behind package-level variables so the regression
1109	// tests (including the batch-import entry-point tests in the cmd/govflow
1110	// package) can make a chosen step of a real save fail deterministically, on the
1111	// save's actual target rather than a neighboring unusable path. Production
1112	// behavior is exactly the wrapped os operations; production code never swaps
1113	// them.
1114	var (
1115		WriteTempContent = func(f *os.File, data []byte) (int, error) { return f.Write(data) }
1116		RenameTempFile   = os.Rename
1117	)
1118	
1119	// errUnreachablePathLink is the refusal reason for a registry path that runs
1120	// into a symbolic link whose target cannot be resolved — a dangling link or a
1121	// link loop, on a directory component as well as on the final component. It
1122	// is deliberately worded as an unusable link, not as a registry file that has
1123	// merely not been created: the two are indistinguishable from ReadFile's
1124	// fs.ErrNotExist alone, and only the former is a first registration.
1125	var errUnreachablePathLink = errors.New("a symbolic link in the registry path has a target that does not exist or cannot be resolved")
1126	
1127	// checkRegistryPathReachable decides, before the registry bytes are read,
1128	// whether path can reach anything the way the kernel resolves names. It
1129	// exists because os.ReadFile reports fs.ErrNotExist both for a registry file
1130	// that has never been created (a legitimate first registration) and for a
1131	// path that descends through a dangling directory symbolic link (not one):
1132	// with work/alias pointing at a missing directory, ReadFile on
1133	// work/alias/batches.json — and, because the kernel cannot step ".." out of
1134	// a directory the link never reaches, on work/alias/../batches.json too —
1135	// returns exactly the not-exist error even when work/batches.json exists.
1136	//
1137	// The check climbs through the raw components missing from the filesystem
1138	// (never by lexical cleaning, which would collapse "alias/.." before the
1139	// kernel resolves alias) to the longest existing prefix. A ".." among the
1140	// missing components is harmless here: without a symbolic link in the path
1141	// the prefix genuinely exists, so such a path is either a real file (read
1142	// normally) or a path through missing ordinary directories, and reading is
1143	// allowed either way — the read creates nothing and Save runs its own
1144	// stricter refusal before writing. What must fail is an existing prefix that
1145	// is itself a symbolic link which cannot be chased to a real directory:
1146	// EvalSymlinks on the prefix names exactly that failure for a dangling
1147	// link or a link loop, including one reached through several links. A
1148	// relative link target is resolved by EvalSymlinks against the link's own
1149	// directory, matching the kernel. The check only calls Lstat and
1150	// EvalSymlinks, so it never creates a directory, registry file or temporary
1151	// file and never modifies a link.
1152	func checkRegistryPathReachable(path string) error {
1153		cur := path
1154		for {
1155			info, err := os.Lstat(cur)
1156			if err == nil {
1157				// cur is the longest existing prefix. A prefix that is itself a
1158				// symbolic link which cannot be chased to a real directory is the
1159				// one failure that looks like a never-created registry file: the
1160				// final read reports fs.ErrNotExist either way. EvalSymlinks
1161				// resolves an absolute link target, or a relative one against the
1162				// link's own directory (never the process working directory),
1163				// through every hop of a chain; a dangling link or a loop fails
1164				// here. Any other failure at a deeper component (for example
1165				// permission denied) is left for the read itself to report.
1166				if info.Mode()&os.ModeSymlink != 0 {
1167					if _, eerr := filepath.EvalSymlinks(cur); eerr != nil {
1168						return errUnreachablePathLink
1169					}
1170				}
1171				return nil
1172			}
1173			parent, _ := rawParent(cur)
1174			if parent == cur {
1175				// No existing prefix at all: a bare relative name resolved
1176				// against the process working directory, the same way an
1177				// ordinary open would. No symbolic link could have been
1178				// encountered, so a not-exist is an ordinary first registration
1179				// and any other failure is the read's own to report.
1180				return nil
1181			}
1182			cur = parent
1183		}
1184	}
