1186	// resolveRegistryTarget returns the real file a save to path must replace,
1187	// resolved the same way the kernel resolves path for reads: every symbolic
1188	// link is chased — links on DIRECTORY components included — and every ".."
1189	// steps out of the directory it really leaves, not out of the link's own
1190	// parent name. The result is a cleaned path with no link or ".." component
1191	// naming exactly the file Load read, so the temporary file and the rename
1192	// land in the target's real directory (a relative path stays relative,
1193	// resolved against the process working directory as the input was).
1194	//
1195	// Physical resolution is what keeps read and save locations identical when a
1196	// directory link is followed by "..": with work/alias -> store/child, the
1197	// path work/alias/../batches.json means store/batches.json. Lexical cleaning
1198	// (filepath.Clean, filepath.Dir) collapses alias/.. to work and would save
1199	// next to the link — into an unrelated, possibly read-only directory.
1200	// Components missing from the filesystem (a first registration) are appended
1201	// verbatim onto the longest existing prefix, so creating a new file needs
1202	// write permission only in the directory that really holds it.
1203	//
1204	// A path that descends into a directory that does not exist and only then
1205	// climbs back with ".." — store/missing/../batches.json with no store/missing
1206	// — cannot reach any file the way the kernel resolves names, so it is an
1207	// error rather than a first registration: the save neither creates the
1208	// missing directory (which would turn an unresolvable path into a live one)
1209	// nor writes the lexically cleaned name (store/batches.json), which may be an
1210	// unrelated existing registry. A path that only creates new directories
1211	// without climbing back out (store/new/batches.json), or climbs ".." after a
1212	// prefix that really exists, is resolved and saved normally.
1213	//
1214	// A dangling symbolic link or a link loop — on the final component or on a
1215	// directory leading to it — is an error: the save must not create the target
1216	// or overwrite the link as if this were a first registration.
1217	func resolveRegistryTarget(path string) (string, error) {
1218		// Climb through components missing from the filesystem by stripping raw
1219		// path segments, never by lexical cleaning: filepath.Clean would collapse
1220		// "alias/.." against the link's own parent name before the kernel ever
1221		// resolves alias, sending the save at work/x.json instead of store/x.json.
1222		// os.Lstat resolves every component but the last exactly as the kernel
1223		// does, so each surviving prefix is checked with its real meaning.
1224		cur := path
1225		var tail []string
1226		for {
1227			info, err := os.Lstat(cur)
1228			if err == nil {
1229				// Refuse a ".." among the not-yet-existing components that climbs
1230				// back out of a directory which would first have to be created:
1231				// the user's path itself cannot name anything there, and creating
1232				// the directory would make a previously unresolvable path valid.
1233				if missing, escape := missingDirDotDotEscape(tail); escape {
1234					return "", errEscapeThroughMissingDir(missing)
1235				}
1236				// cur is the longest existing prefix. Resolve it physically: an
1237				// absolute link target, or a relative one resolved against the
1238				// link's own directory (never the process working directory), is
1239				// followed; a dangling link or a loop fails here and is reported
1240				// as an unusable symbolic link rather than a fresh-registry path.
1241				base, eerr := filepath.EvalSymlinks(cur)
1242				if eerr != nil {
1243					if info.Mode()&os.ModeSymlink != 0 {
1244						return "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", eerr)
1245					}
1246					return "", fmt.Errorf("cannot inspect registry path: %w", eerr)
1247				}
1248				// Append the not-yet-existing components verbatim: a first
1249				// registration needs write permission only in the real directory
1250				// that will hold the file, never in directories merely traversed.
1251				target := base
1252				for i := len(tail) - 1; i >= 0; i-- {
1253					target = filepath.Join(target, tail[i])
1254				}
1255				return filepath.Clean(target), nil
1256			}
1257			if !errors.Is(err, fs.ErrNotExist) {
1258				return "", fmt.Errorf("cannot inspect registry path: %w", err)
1259			}
1260			parent, base := rawParent(cur)
1261			tail = append(tail, base)
1262			if parent == cur {
1263				// A bare relative name with no existing prefix: it names a file
1264				// in the process working directory, just as a plain open would —
1265				// unless it climbs ".." out of a directory that does not exist.
1266				if missing, escape := missingDirDotDotEscape(tail); escape {
1267					return "", errEscapeThroughMissingDir(missing)
1268				}
1269				return filepath.Clean(path), nil
1270			}
1271			cur = parent
1272		}
1273	}
1274	
1275	// missingDirDotDotEscape inspects the raw components stripped while climbing
1276	// to the longest existing prefix. tail holds them from the registry file end
1277	// (tail[0] is the final, registry-file component) toward the existing prefix
1278	// (tail[len-1] sits next to it). A ".." that climbs out of a directory
1279	// descended into only within the not-yet-existing tail marks exactly the
1280	// unresolvable shape — store/missing/../batches.json — that must be refused:
1281	// the kernel cannot resolve the ".." until "missing" exists, and it never
1282	// legitimately exists on this path.
1283	//
1284	// The final component is the registry file name, never a directory descent,
1285	// so tail[0] is not counted. ".." steps matched by an equally non-existent
1286	// descent keep the lexical depth positive and do not cancel the violation:
1287	// the first ".." that leaves a missing directory is already fatal. The
1288	// returned name is the missing directory that ".." immediately tries to
1289	// leave. Symlinked or genuinely existing components never reach tail, so
1290	// this never trips over a physical ".." (as after work/alias -> store/child).
1291	func missingDirDotDotEscape(tail []string) (missing string, escape bool) {
1292		depth := 0
1293		lastMissing := ""
1294		// Walk from the existing-prefix side toward the file.
1295		for i := len(tail) - 1; i >= 1; i-- {
1296			switch tail[i] {
1297			case ".", "":
1298				// A "." (or the empty segment of a doubled separator) is a
1299				// lexical no-op even in the not-yet-existing tail.
1300			case "..":
1301				if depth > 0 {
1302					return lastMissing, true
1303				}
1304				depth--
1305			default:
1306				depth++
1307				lastMissing = tail[i]
1308			}
1309		}
1310		return "", false
1311	}
1312	
1313	// errEscapeThroughMissingDir is the refusal reason for a registry path that
1314	// descends into a non-existent directory and then climbs back with "..". The
1315	// Save wrapper adds the user-supplied path; the missing directory is named so
1316	// the user can see which component made the path unresolvable.
1317	func errEscapeThroughMissingDir(missing string) error {
1318		return fmt.Errorf(
1319			"the path descends through directory %s, which does not exist, and then climbs back with \"..\"; "+
1320				"such a path cannot reach an existing file and the missing directory is not created to make it valid, so the registry is not written",
1321			strconv.Quote(missing))
1322	}
1323	
1324	// rawParent splits path at its final separator without resolving "..", so the
1325	// caller can climb one raw component at a time and keep physical resolution of
1326	// any directory link in the surviving prefix.
1327	func rawParent(path string) (parent, base string) {
1328		i := strings.LastIndexByte(path, os.PathSeparator)
1329		if i < 0 {
1330			return path, path
1331		}
1332		return path[:i], path[i+1:]
1333	}
1334	
1335	// Save atomically writes reg to path, replacing the file only after the new
1336	// content is fully on disk so an existing registry stays usable on failure.
1337	// Records are serialized in their current order; the file is created with
1338	// 0644 permissions or, when replacing an existing file, with its permissions.
1339	//
1340	// When path reaches the registry through a symbolic link, the link's target
1341	// is the file replaced: the new content is prepared next to the target and
1342	// moved over it, so the link stays a link to the same target and the target
1343	// keeps its permissions, while reads through either the link or the real
1344	// path see the saved records. This holds for a link on the final component
1345	// and for a link on a DIRECTORY component, including a ".." that steps back
1346	// after it: with work/alias -> store/child, work/alias/../batches.json is
1347	// store/batches.json, and the save writes there even though the directory
1348	// containing the link (here work) is not writable — write access is needed
1349	// only in the target's real directory. A link whose target does not exist,
1350	// or a link loop, on the file or on a leading directory, rejects the save
1351	// with an error naming path — the target is never created and the link is
1352	// never replaced.
1353	//
1354	// A path that descends through a directory that does not exist and only then
1355	// climbs back with ".." (store/missing/../batches.json with store/missing
1356	// absent) is likewise rejected before anything is written: such a path
1357	// reaches no file the way the kernel resolves names, so the save neither
1358	// creates the missing directory — which would turn the unresolvable path into
1359	// a live one — nor writes the lexically cleaned name, where an unrelated
1360	// registry could be overwritten. A ".." after a directory that genuinely
1361	// exists, including the real target of a directory symlink, still resolves by
1362	// real directory relations, and a not-yet-existing parent that is never
1363	// climbed out of (store/new/batches.json) is created as on any first save.
1364	//
1365	// Every record must satisfy the same effective-value rules Load enforces, so
1366	// a registry saved successfully always reads back: batch, product and unit
1367	// must be non-empty valid UTF-8 text (kept verbatim — no trimming or case
1368	// folding, so whitespace-only text is ordinary non-empty text), quantity
1369	// must lie in 1..MaxQuantity, and batch ids must be unique under exact
1370	// byte-for-byte comparison, two identical records included. Any violation
1371	// rejects the whole save before anything is written: an existing target
1372	// keeps its bytes and modification time, a missing target stays missing and
1373	// no temporary file is left behind. A nil or empty Batches is a legal empty
1374	// registry and is written as "batches": [] without touching reg itself.
1375	func Save(path string, reg *Registry) error {
1376		if reg.Version != FormatVersion {
1377			return fmt.Errorf("cannot write registry format version %d", reg.Version)
1378		}
1379		if err := validateForSave(reg); err != nil {
1380			return fmt.Errorf("cannot save registry %q: %w", path, err)
1381		}
1382		target, err := resolveRegistryTarget(path)
1383		if err != nil {
1384			return fmt.Errorf("cannot save registry %q: %w", path, err)
1385		}
1386		mode := os.FileMode(0o644)
1387		if info, err := os.Stat(target); err == nil {
1388			mode = info.Mode().Perm()
1389		} else if !errors.Is(err, fs.ErrNotExist) {
1390			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
1391		}
1392	
1393		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
1394			return fmt.Errorf("cannot save registry %q: %w", path, err)
1395		}
1396	
1397		// Encode a shallow copy so a nil Batches marshals as [] (null would not
1398		// read back) without mutating the caller's registry.
1399		out := *reg
1400		if out.Batches == nil {
1401			out.Batches = []Batch{}
1402		}
1403		var buf bytes.Buffer
1404		enc := json.NewEncoder(&buf)
1405		enc.SetEscapeHTML(false)
1406		enc.SetIndent("", "  ")
1407		if err := enc.Encode(&out); err != nil {
1408			return fmt.Errorf("cannot encode registry %q: %w", path, err)
1409		}
1410	
1411		tmp, err := os.CreateTemp(filepath.Dir(target), ".govflow-registry-*.tmp")
1412		if err != nil {
1413			return fmt.Errorf("cannot save registry %q: %w", path, err)
1414		}
1415		tmpName := tmp.Name()
1416		abort := func(cause error) error {
1417			tmp.Close()
1418			os.Remove(tmpName)
1419			return fmt.Errorf("cannot save registry %q: %w", path, cause)
1420		}
1421		if _, err := WriteTempContent(tmp, buf.Bytes()); err != nil {
1422			return abort(err)
1423		}
1424		if err := tmp.Chmod(mode); err != nil {
1425			return abort(err)
1426		}
