	for _, userPath := range paths {
		t.Run(filepath.Base(filepath.Clean(userPath+sep))+strings.TrimPrefix(userPath, dir), func(t *testing.T) {
			submitted := []Batch{saveBatch("NEW", "P-9", 5, "box")}
