// The directory-marker shapes, assembled WITHOUT filepath.Clean/Join so the
// trailing separator and the final "."/".." reach the package exactly as a
// user types them. Each is paired with the base name that a stripping save
// would wrongly create ("store/new.json/" would create "store/new.json";
// "store/new/." would create "store/new").
func directoryShapeCases(store string) []struct {
	name   string
	path   string
	stripped string
} {
	sep := string(os.PathSeparator)
	return []struct {
		name   string
		path   string
		stripped string
	}{
		{"trailing slash", store + sep + "new.json" + sep, filepath.Join(store, "new.json")},
		{"two trailing slashes", store + sep + "new.json" + sep + sep, filepath.Join(store, "new.json")},
		{"final dot", store + sep + "new" + sep + ".", filepath.Join(store, "new")},
		{"final dot-dot", store + sep + "new" + sep + "..", filepath.Join(store, "new")},
	}
}

